export default {"file":"admin-report-cards.html","title":"Admin - Report Cards Management","htmlClass":"","bodyClass":"","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n\r\n<!-- SVG Icon Sprite -->\r\n<svg width=\"0\" height=\"0\" style=\"position:absolute\" aria-hidden=\"true\">\r\n  <defs>\r\n    <symbol id=\"i-clipboard\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"8\" y=\"2\" width=\"8\" height=\"4\" rx=\"1\"/><path d=\"M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2\"/><path d=\"M9 12h6M9 16h4\"/></symbol>\r\n    <symbol id=\"i-lock\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 10 0v4\"/></symbol>\r\n    <symbol id=\"i-unlock\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"11\" width=\"18\" height=\"11\" rx=\"2\"/><path d=\"M7 11V7a5 5 0 0 1 9.9-1\"/></symbol>\r\n    <symbol id=\"i-search\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-3.5-3.5\"/></symbol>\r\n    <symbol id=\"i-filter\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 5h18l-7 9v6l-4-2v-4z\"/></symbol>\r\n    <symbol id=\"i-refresh\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12a9 9 0 1 1-3-6.7L21 8\"/><path d=\"M21 3v5h-5\"/></symbol>\r\n    <symbol id=\"i-chart\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 3v18h18\"/><path d=\"M7 15l4-4 3 3 5-6\"/></symbol>\r\n    <symbol id=\"i-percent\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"19\" y1=\"5\" x2=\"5\" y2=\"19\"/><circle cx=\"6.5\" cy=\"6.5\" r=\"2.5\"/><circle cx=\"17.5\" cy=\"17.5\" r=\"2.5\"/></symbol>\r\n    <symbol id=\"i-check\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 6 9 17l-5-5\"/></symbol>\r\n    <symbol id=\"i-award\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"9\" r=\"6\"/><path d=\"m8.5 13.5-1.5 8 5-3 5 3-1.5-8\"/></symbol>\r\n    <symbol id=\"i-eye\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8S1 12 1 12z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></symbol>\r\n    <symbol id=\"i-print\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9V2h12v7\"/><rect x=\"4\" y=\"9\" width=\"16\" height=\"9\" rx=\"2\"/><path d=\"M6 18h12v4H6z\"/></symbol>\r\n    <symbol id=\"i-trash\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 6h18\"/><path d=\"M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2\"/><path d=\"M6 6l1 14a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2l1-14\"/></symbol>\r\n    <symbol id=\"i-close\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 6 6 18M6 6l12 12\"/></symbol>\r\n    <symbol id=\"i-crown\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 6l4 6 5-8 5 8 4-6-2 13H5z\"/></symbol>\r\n    <symbol id=\"i-user\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21a8 8 0 0 1 16 0\"/></symbol>\r\n    <symbol id=\"i-alert\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3 2 20h20z\"/><path d=\"M12 9v5\"/><circle cx=\"12\" cy=\"17.5\" r=\"0.5\" fill=\"currentColor\"/></symbol>\r\n    <symbol id=\"i-empty\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><path d=\"M14 2v6h6\"/><path d=\"M9 15h6M9 11h2\"/></symbol>\r\n  </defs>\r\n</svg>\r\n\r\n<div class=\"container\">\r\n  <div class=\"header\">\r\n    <div>\r\n      <h1><svg class=\"icon-lg\"><use href=\"#i-clipboard\"/></svg> Report Cards Management</h1>\r\n      <p>View, manage, and analyze student report cards</p>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"content\">\r\n    <div id=\"lockBanner\" class=\"lock-banner\">\r\n      <svg class=\"icon-lg\"><use href=\"#i-lock\"/></svg>\r\n      <div><strong>Selected term is locked.</strong> Teachers cannot edit marks or regenerate report cards for this term. Admin edits from this page are still allowed.</div>\r\n    </div>\r\n    <div id=\"liveBanner\" class=\"live-banner\">\r\n      <svg class=\"icon-lg\"><use href=\"#i-check\"/></svg>\r\n      <div><strong>Selected term is live.</strong> Students with cleared dues can now view this term's report cards.</div>\r\n    </div>\r\n\r\n    <h2 class=\"section-title\"><svg class=\"icon\"><use href=\"#i-lock\"/></svg> Term-wise Report Card Lock</h2>\r\n    <div class=\"term-lock-panel\">\r\n      <div>\r\n        <div class=\"term-lock-title\">Lock one term at a time</div>\r\n        <div class=\"term-lock-note\">When a term is locked, teachers can only view marks/report cards for that term. Admin can still edit marks here.</div>\r\n      </div>\r\n      <select id=\"termLockSelect\" onchange=\"onTermLockSelectChange()\">\r\n        <option value=\"\">Loading terms...</option>\r\n      </select>\r\n      <span id=\"termLockStatus\" class=\"term-lock-status unlocked\"><svg class=\"icon-sm\"><use href=\"#i-unlock\"/></svg><span>Unlocked</span></span>\r\n      <button id=\"termLockToggleBtn\" class=\"danger\" onclick=\"toggleSelectedTermLock()\">\r\n        <svg class=\"icon\"><use href=\"#i-lock\"/></svg>\r\n        <span id=\"termLockToggleText\">Lock Term</span>\r\n      </button>\r\n    </div>\r\n\r\n    <h2 class=\"section-title\"><svg class=\"icon\"><use href=\"#i-eye\"/></svg> Result Visibility</h2>\r\n    <div class=\"term-lock-panel\">\r\n      <div>\r\n        <div class=\"term-lock-title\">Make one term live for students</div>\r\n        <div class=\"term-lock-note\">Teacher/admin reports stay private until this is turned live. Existing fee-dues lock still applies for students.</div>\r\n      </div>\r\n      <select id=\"termLiveSelect\" onchange=\"onTermLiveSelectChange()\">\r\n        <option value=\"\">Loading terms...</option>\r\n      </select>\r\n      <span id=\"termLiveStatus\" class=\"term-lock-status hidden\"><svg class=\"icon-sm\"><use href=\"#i-lock\"/></svg><span>Hidden</span></span>\r\n      <button id=\"termLiveToggleBtn\" class=\"success\" onclick=\"toggleSelectedTermLive()\">\r\n        <svg class=\"icon\"><use href=\"#i-eye\"/></svg>\r\n        <span id=\"termLiveToggleText\">Make Live</span>\r\n      </button>\r\n    </div>\r\n\r\n    <h2 class=\"section-title\"><svg class=\"icon\"><use href=\"#i-filter\"/></svg> Search and Filter</h2>\r\n    <div class=\"filters-section\">\r\n      <input type=\"text\" id=\"searchName\" placeholder=\"Search by student name...\">\r\n      <input type=\"text\" id=\"searchStudentId\" placeholder=\"Search by student ID...\">\r\n      <input type=\"text\" id=\"searchClass\" placeholder=\"Search by class (e.g. 10-A)\">\r\n      <select id=\"gradeFilter\">\r\n        <option value=\"\">All Grades</option>\r\n        <option value=\"A+\">Grade A+</option>\r\n        <option value=\"A\">Grade A</option>\r\n        <option value=\"B\">Grade B</option>\r\n        <option value=\"C\">Grade C</option>\r\n        <option value=\"F\">Grade F</option>\r\n      </select>\r\n      <select id=\"termFilter\">\r\n        <option value=\"\">All Terms</option>\r\n      </select>\r\n      <div class=\"button-group\">\r\n        <button class=\"primary\" onclick=\"applyFilters()\"><svg class=\"icon\"><use href=\"#i-search\"/></svg> Search</button>\r\n        <button class=\"secondary\" onclick=\"resetFilters()\"><svg class=\"icon\"><use href=\"#i-refresh\"/></svg> Reset</button>\r\n      </div>\r\n    </div>\r\n\r\n    <h2 class=\"section-title\"><svg class=\"icon\"><use href=\"#i-user\"/></svg> Class-wise Results</h2>\r\n    <div class=\"class-results-panel\">\r\n      <div>\r\n        <div class=\"class-results-title\">View report cards by class-section</div>\r\n        <div class=\"class-results-note\">Select a class and section to list all generated student results below.</div>\r\n      </div>\r\n      <select id=\"classResultSelect\" onchange=\"populateClassResultSections()\">\r\n        <option value=\"\">All Classes</option>\r\n      </select>\r\n      <select id=\"sectionResultSelect\">\r\n        <option value=\"\">All Sections</option>\r\n      </select>\r\n      <button class=\"primary\" onclick=\"showClassWiseResults()\"><svg class=\"icon\"><use href=\"#i-search\"/></svg> Show Results</button>\r\n    </div>\r\n\r\n    <h2 class=\"section-title\"><svg class=\"icon\"><use href=\"#i-chart\"/></svg> Statistics</h2>\r\n    <div class=\"stats-grid\" id=\"statsGrid\" style=\"display:none;\">\r\n      <div class=\"stat-card\">\r\n        <div class=\"stat-icon-wrap\"><svg class=\"icon-lg\"><use href=\"#i-clipboard\"/></svg></div>\r\n        <div><div class=\"stat-label\">Total Reports</div><div class=\"stat-value\" id=\"totalReports\">0</div></div>\r\n      </div>\r\n      <div class=\"stat-card secondary\">\r\n        <div class=\"stat-icon-wrap\"><svg class=\"icon-lg\"><use href=\"#i-percent\"/></svg></div>\r\n        <div><div class=\"stat-label\">Average %</div><div class=\"stat-value\" id=\"avgPercentage\">0%</div></div>\r\n      </div>\r\n      <div class=\"stat-card success\">\r\n        <div class=\"stat-icon-wrap\"><svg class=\"icon-lg\"><use href=\"#i-check\"/></svg></div>\r\n        <div><div class=\"stat-label\">Passed Students</div><div class=\"stat-value\" id=\"passedCount\">0</div></div>\r\n      </div>\r\n      <div class=\"stat-card warning\">\r\n        <div class=\"stat-icon-wrap\"><svg class=\"icon-lg\"><use href=\"#i-award\"/></svg></div>\r\n        <div><div class=\"stat-label\">A+ Grades</div><div class=\"stat-value\" id=\"aPlusCount\">0</div></div>\r\n      </div>\r\n    </div>\r\n\r\n    <h2 class=\"section-title\"><svg class=\"icon\"><use href=\"#i-clipboard\"/></svg> All Report Cards</h2>\r\n    <div class=\"table-wrapper\">\r\n      <table>\r\n        <thead>\r\n          <tr>\r\n            <th>Student Name</th>\r\n            <th>Student ID</th>\r\n            <th>Class</th>\r\n            <th>Percentage</th>\r\n            <th>Grade</th>\r\n            <th>Term</th>\r\n            <th>Generated By</th>\r\n            <th>Date</th>\r\n            <th>Actions</th>\r\n          </tr>\r\n        </thead>\r\n        <tbody id=\"tableBody\">\r\n          <tr><td colspan=\"9\" class=\"loading\"><span class=\"spinner\"></span> Loading...</td></tr>\r\n        </tbody>\r\n      </table>\r\n    </div>\r\n  </div>\r\n</div>\r\n\r\n<div id=\"reportModal\" class=\"modal\">\r\n  <div class=\"modal-content\">\r\n    <div class=\"modal-header\">\r\n      <h2><svg class=\"icon-lg\"><use href=\"#i-clipboard\"/></svg> Report Card Details</h2>\r\n      <button type=\"button\" class=\"modal-close\" onclick=\"closeModal(event)\" aria-label=\"Close report card details\"><svg class=\"icon-lg\"><use href=\"#i-close\"/></svg></button>\r\n    </div>\r\n    <div class=\"modal-body\" id=\"modalBody\">Loading...</div>\r\n  </div>\r\n</div>\r\n\r\n<script type=\"module\">\r\nimport { initializeApp } from \"./firebase-compat.js\";\r\nimport { getFirestore, collection, query, orderBy, getDocs, doc, getDoc, setDoc, deleteDoc } from \"./firebase-compat.js\";\r\nimport { getAuth, onAuthStateChanged } from \"./firebase-compat.js\";\r\n\r\nconst firebaseConfig = {\r\n  apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n  authDomain: \"schoolix-48107.firebaseapp.com\",\r\n  projectId: \"schoolix-48107\",\r\n  storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n  messagingSenderId: \"133937954491\",\r\n  appId: \"1:133937954491:web:69d8064422617eb8c4339e\",\r\n  measurementId: \"G-EG23XE5Q0Z\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst db = getFirestore(app);\r\nconst auth = getAuth(app);\r\nconst RESULT_NOTIFICATION_SEND_URL = \"https://ezkmeedcqetztkeppxil.supabase.co/functions/v1/send-app-notification\";\r\nconst RESULT_NOTIFICATION_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImV6a21lZWRjcWV0enRrZXBweGlsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzgxMjk5NjAsImV4cCI6MjA5MzcwNTk2MH0.1davJ_NYkFhHToUtcFBR0kA6dk0-cOkaIbK2SCObkQg\";\r\n\r\nlet allReports = [];\r\nlet allTerms = [];\r\nlet reportTermLocks = {};\r\nlet reportTermVisibility = {};\r\nlet currentAdminId = null;\r\nlet activeSessionId = \"\";\r\nlet activeSessionLabel = \"\";\r\nlet selectedLockTermKey = \"\";\r\nlet selectedLiveTermKey = \"\";\r\n\r\nasync function loadActiveSession() {\r\n  activeSessionId = \"\";\r\n  activeSessionLabel = \"\";\r\n  try {\r\n    let viewSessionId = \"\";\r\n    try { viewSessionId = localStorage.getItem(\"schoolix.viewSessionId\") || \"\"; } catch (_) {}\r\n    const activeSnap = await getDoc(doc(db, \"schools\", currentAdminId, \"settings\", \"activeSession\"));\r\n    activeSessionId = viewSessionId || (activeSnap.exists() ? activeSnap.data().sessionId || \"\" : \"\");\r\n    if (!activeSessionId) return;\r\n    const sessionSnap = await getDoc(doc(db, \"schools\", currentAdminId, \"sessions\", activeSessionId));\r\n    if (!sessionSnap.exists()) {\r\n      try { if (viewSessionId) localStorage.removeItem(\"schoolix.viewSessionId\"); } catch (_) {}\r\n      activeSessionId = activeSnap.exists() ? activeSnap.data().sessionId || \"\" : \"\";\r\n      if (!activeSessionId || activeSessionId === viewSessionId) return;\r\n      const fallbackSnap = await getDoc(doc(db, \"schools\", currentAdminId, \"sessions\", activeSessionId));\r\n      if (!fallbackSnap.exists()) return;\r\n      const fallbackData = fallbackSnap.data();\r\n      activeSessionLabel = fallbackData.session || fallbackData.name || \"\";\r\n      return;\r\n    }\r\n    const data = sessionSnap.data();\r\n    activeSessionLabel = data.session || data.name || \"\";\r\n  } catch (e) { console.error(\"Session load error:\", e); }\r\n}\r\n\r\nfunction normalizeTermKey(value) {\r\n  return String(value || \"\").trim().toLowerCase().replace(/[^a-z0-9]+/g, \"-\").replace(/^-+|-+$/g, \"\");\r\n}\r\n\r\nfunction getTermLabel(termKey) {\r\n  return allTerms.find((term) => term.termKey === termKey)?.label || termKey || \"Selected term\";\r\n}\r\n\r\nfunction getTermLockKey(termKey) {\r\n  if (!termKey) return \"\";\r\n  return activeSessionId ? `${activeSessionId}__${termKey}` : termKey;\r\n}\r\n\r\nfunction isTermLocked(termKey) {\r\n  return reportTermLocks[getTermLockKey(termKey)]?.locked === true;\r\n}\r\n\r\nfunction getTermVisibilityKey(termKey) {\r\n  return getTermLockKey(termKey);\r\n}\r\n\r\nfunction isTermLive(termKey) {\r\n  return reportTermVisibility[getTermVisibilityKey(termKey)]?.live === true;\r\n}\r\n\r\nasync function sendResultLiveNotification(termLabel) {\r\n  const token = await auth.currentUser?.getIdToken(true);\r\n  if (!token) return;\r\n  const response = await fetch(RESULT_NOTIFICATION_SEND_URL, {\r\n    method: \"POST\",\r\n    headers: {\r\n      \"Content-Type\": \"application/json\",\r\n      \"apikey\": RESULT_NOTIFICATION_ANON_KEY,\r\n      \"Authorization\": `Bearer ${RESULT_NOTIFICATION_ANON_KEY}`,\r\n      \"x-firebase-auth\": token\r\n    },\r\n    body: JSON.stringify({\r\n      title: \"Result is live\",\r\n      message: `${termLabel} result is now live. Students with cleared dues can view it in the app.`,\r\n      audience: \"students\"\r\n    })\r\n  });\r\n  if (!response.ok) throw new Error(await response.text());\r\n}\r\n\r\nfunction getReportTermKey(report = {}) {\r\n  return report.termKey || normalizeTermKey(report.termLabel || report.term || \"\");\r\n}\r\n\r\nasync function loadTermsAndLocks() {\r\n  allTerms = [];\r\n  reportTermLocks = {};\r\n  reportTermVisibility = {};\r\n  try {\r\n    const termSnap = await getDocs(collection(db, \"schools\", currentAdminId, \"terms\"));\r\n    const unique = new Map();\r\n    termSnap.docs\r\n      .map(d => ({ id: d.id, ...d.data() }))\r\n      .filter(term => {\r\n        if (!activeSessionId && !activeSessionLabel) return true;\r\n        if (!term.sessionId && !term.session && !term.currentYear && !term.academicSession) return true;\r\n        return term.sessionId === activeSessionId ||\r\n          term.session === activeSessionLabel ||\r\n          term.currentYear === activeSessionLabel ||\r\n          term.academicSession === activeSessionLabel;\r\n      })\r\n      .forEach(term => {\r\n        const termKey = term.termKey || normalizeTermKey(term.label || term.term || term.name || term.id);\r\n        if (!termKey) return;\r\n        unique.set(termKey, {\r\n          ...term,\r\n          termKey,\r\n          label: term.label || term.term || term.name || termKey\r\n        });\r\n      });\r\n    allTerms = Array.from(unique.values()).sort((a, b) => (a.createdAt?.seconds || 0) - (b.createdAt?.seconds || 0));\r\n\r\n    const lockSnap = await getDoc(doc(db, \"schools\", currentAdminId, \"settings\", \"reportCardTermLocks\"));\r\n    reportTermLocks = lockSnap.exists() ? (lockSnap.data().locks || {}) : {};\r\n    const visibilitySnap = await getDoc(doc(db, \"schools\", currentAdminId, \"settings\", \"reportCardTermVisibility\"));\r\n    reportTermVisibility = visibilitySnap.exists() ? (visibilitySnap.data().terms || {}) : {};\r\n  } catch (e) { console.error(\"Term lock load error:\", e); }\r\n  populateTermControls();\r\n  updateTermLockUI();\r\n  updateTermLiveUI();\r\n}\r\n\r\nfunction populateTermControls() {\r\n  const lockSelect = document.getElementById(\"termLockSelect\");\r\n  const liveSelect = document.getElementById(\"termLiveSelect\");\r\n  const filterSelect = document.getElementById(\"termFilter\");\r\n  if (lockSelect) {\r\n    lockSelect.innerHTML = allTerms.length\r\n      ? allTerms.map(term => `<option value=\"${escapeHtml(term.termKey)}\">${escapeHtml(term.label)}</option>`).join(\"\")\r\n      : '<option value=\"\">No terms found</option>';\r\n    if (!selectedLockTermKey || !allTerms.some(term => term.termKey === selectedLockTermKey)) {\r\n      selectedLockTermKey = allTerms[0]?.termKey || \"\";\r\n    }\r\n    lockSelect.value = selectedLockTermKey;\r\n  }\r\n  if (liveSelect) {\r\n    liveSelect.innerHTML = allTerms.length\r\n      ? allTerms.map(term => `<option value=\"${escapeHtml(term.termKey)}\">${escapeHtml(term.label)}</option>`).join(\"\")\r\n      : '<option value=\"\">No terms found</option>';\r\n    if (!selectedLiveTermKey || !allTerms.some(term => term.termKey === selectedLiveTermKey)) {\r\n      selectedLiveTermKey = selectedLockTermKey || allTerms[0]?.termKey || \"\";\r\n    }\r\n    liveSelect.value = selectedLiveTermKey;\r\n  }\r\n  if (filterSelect) {\r\n    const current = filterSelect.value;\r\n    filterSelect.innerHTML = '<option value=\"\">All Terms</option>' +\r\n      allTerms.map(term => `<option value=\"${escapeHtml(term.termKey)}\">${escapeHtml(term.label)}</option>`).join(\"\");\r\n    filterSelect.value = allTerms.some(term => term.termKey === current) ? current : \"\";\r\n  }\r\n}\r\n\r\nfunction updateTermLockUI() {\r\n  const btn = document.getElementById(\"termLockToggleBtn\");\r\n  const btnText = document.getElementById(\"termLockToggleText\");\r\n  const btnIcon = btn?.querySelector(\"svg use\");\r\n  const status = document.getElementById(\"termLockStatus\");\r\n  const statusText = status?.querySelector(\"span\");\r\n  const statusIcon = status?.querySelector(\"svg use\");\r\n  const banner = document.getElementById(\"lockBanner\");\r\n  const locked = isTermLocked(selectedLockTermKey);\r\n\r\n  if (!selectedLockTermKey) {\r\n    if (btn) btn.disabled = true;\r\n    if (statusText) statusText.textContent = \"No term\";\r\n    if (banner) banner.classList.remove(\"show\");\r\n    return;\r\n  }\r\n  if (btn) btn.disabled = false;\r\n  if (locked) {\r\n    btn.classList.remove(\"danger\"); btn.classList.add(\"success\");\r\n    btnText.textContent = \"Unlock Term\";\r\n    btnIcon?.setAttribute(\"href\", \"#i-unlock\");\r\n    status.classList.remove(\"unlocked\"); status.classList.add(\"locked\");\r\n    statusText.textContent = \"Locked\";\r\n    statusIcon?.setAttribute(\"href\", \"#i-lock\");\r\n    banner.classList.add(\"show\");\r\n  } else {\r\n    btn.classList.remove(\"success\"); btn.classList.add(\"danger\");\r\n    btnText.textContent = \"Lock Term\";\r\n    btnIcon?.setAttribute(\"href\", \"#i-lock\");\r\n    status.classList.remove(\"locked\"); status.classList.add(\"unlocked\");\r\n    statusText.textContent = \"Unlocked\";\r\n    statusIcon?.setAttribute(\"href\", \"#i-unlock\");\r\n    banner.classList.remove(\"show\");\r\n  }\r\n}\r\n\r\nwindow.onTermLockSelectChange = () => {\r\n  selectedLockTermKey = document.getElementById(\"termLockSelect\").value;\r\n  updateTermLockUI();\r\n};\r\n\r\nwindow.toggleSelectedTermLock = async () => {\r\n  if (!currentAdminId) return;\r\n  if (!selectedLockTermKey) return alert(\"Select a term first.\");\r\n  const newState = !isTermLocked(selectedLockTermKey);\r\n  const label = getTermLabel(selectedLockTermKey);\r\n  const msg = newState\r\n    ? `Lock report cards for ${label}?\\n\\nTeachers will NOT be able to edit marks or regenerate report cards for this term. Admin can still edit from this page.`\r\n    : `Unlock report cards for ${label}?\\n\\nTeachers will be able to edit marks and regenerate report cards for this term again.`;\r\n  if (!confirm(msg)) return;\r\n  try {\r\n    const lockKey = getTermLockKey(selectedLockTermKey);\r\n    reportTermLocks = {\r\n      ...reportTermLocks,\r\n      [lockKey]: {\r\n        locked: newState,\r\n        termKey: selectedLockTermKey,\r\n        termLabel: label,\r\n        sessionId: activeSessionId || \"\",\r\n        session: activeSessionLabel || \"\",\r\n        updatedAt: new Date(),\r\n        updatedBy: auth.currentUser?.uid || \"admin\"\r\n      }\r\n    };\r\n    await setDoc(doc(db, \"schools\", currentAdminId, \"settings\", \"reportCardTermLocks\"), {\r\n      locks: reportTermLocks,\r\n      updatedAt: new Date(),\r\n      updatedBy: auth.currentUser?.uid || \"admin\"\r\n    }, { merge: true });\r\n    updateTermLockUI();\r\n    alert(newState ? `${label} locked successfully.` : `${label} unlocked successfully.`);\r\n  } catch (e) {\r\n    console.error(e);\r\n    alert(\"Failed to update term lock.\");\r\n  }\r\n};\r\n\r\nfunction updateTermLiveUI() {\r\n  const btn = document.getElementById(\"termLiveToggleBtn\");\r\n  const btnText = document.getElementById(\"termLiveToggleText\");\r\n  const btnIcon = btn?.querySelector(\"svg use\");\r\n  const status = document.getElementById(\"termLiveStatus\");\r\n  const statusText = status?.querySelector(\"span\");\r\n  const statusIcon = status?.querySelector(\"svg use\");\r\n  const banner = document.getElementById(\"liveBanner\");\r\n  const live = isTermLive(selectedLiveTermKey);\r\n\r\n  if (!selectedLiveTermKey) {\r\n    if (btn) btn.disabled = true;\r\n    if (statusText) statusText.textContent = \"No term\";\r\n    if (banner) banner.classList.remove(\"show\");\r\n    return;\r\n  }\r\n  if (btn) btn.disabled = false;\r\n  if (live) {\r\n    btn.classList.remove(\"success\"); btn.classList.add(\"warning\");\r\n    btnText.textContent = \"Hide From Students\";\r\n    btnIcon?.setAttribute(\"href\", \"#i-lock\");\r\n    status.classList.remove(\"hidden\"); status.classList.add(\"live\");\r\n    statusText.textContent = \"Live\";\r\n    statusIcon?.setAttribute(\"href\", \"#i-eye\");\r\n    banner.classList.add(\"show\");\r\n  } else {\r\n    btn.classList.remove(\"warning\"); btn.classList.add(\"success\");\r\n    btnText.textContent = \"Make Live\";\r\n    btnIcon?.setAttribute(\"href\", \"#i-eye\");\r\n    status.classList.remove(\"live\"); status.classList.add(\"hidden\");\r\n    statusText.textContent = \"Hidden\";\r\n    statusIcon?.setAttribute(\"href\", \"#i-lock\");\r\n    banner.classList.remove(\"show\");\r\n  }\r\n}\r\n\r\nwindow.onTermLiveSelectChange = () => {\r\n  selectedLiveTermKey = document.getElementById(\"termLiveSelect\").value;\r\n  updateTermLiveUI();\r\n};\r\n\r\nwindow.toggleSelectedTermLive = async () => {\r\n  if (!currentAdminId) return;\r\n  if (!selectedLiveTermKey) return alert(\"Select a term first.\");\r\n  const newState = !isTermLive(selectedLiveTermKey);\r\n  const label = getTermLabel(selectedLiveTermKey);\r\n  const msg = newState\r\n    ? `Make ${label} live?\\n\\nStudents with no pending dues will be able to view this term's result. Students with dues will stay locked.`\r\n    : `Hide ${label} from students?\\n\\nTeachers and admin can still see reports, but students will not see this term.`;\r\n  if (!confirm(msg)) return;\r\n  try {\r\n    const visibilityKey = getTermVisibilityKey(selectedLiveTermKey);\r\n    reportTermVisibility = {\r\n      ...reportTermVisibility,\r\n      [visibilityKey]: {\r\n        live: newState,\r\n        termKey: selectedLiveTermKey,\r\n        termLabel: label,\r\n        sessionId: activeSessionId || \"\",\r\n        session: activeSessionLabel || \"\",\r\n        updatedAt: new Date(),\r\n        updatedBy: auth.currentUser?.uid || \"admin\"\r\n      }\r\n    };\r\n    await setDoc(doc(db, \"schools\", currentAdminId, \"settings\", \"reportCardTermVisibility\"), {\r\n      terms: reportTermVisibility,\r\n      updatedAt: new Date(),\r\n      updatedBy: auth.currentUser?.uid || \"admin\"\r\n    }, { merge: true });\r\n    if (newState) {\r\n      try {\r\n        await sendResultLiveNotification(label);\r\n      } catch (notificationError) {\r\n        console.warn(\"Result live notification failed\", notificationError);\r\n      }\r\n    }\r\n    updateTermLiveUI();\r\n    alert(newState ? `${label} is now live for eligible students.` : `${label} is now hidden from students.`);\r\n  } catch (e) {\r\n    console.error(e);\r\n    alert(\"Failed to update result visibility.\");\r\n  }\r\n};\r\n\r\nfunction reportBelongsToActiveSession(report) {\r\n  if (!activeSessionId && !activeSessionLabel) return true;\r\n  if (!report.sessionId && !report.session && !report.currentYear && !report.academicSession) return false;\r\n  return report.sessionId === activeSessionId ||\r\n    report.session === activeSessionLabel ||\r\n    report.currentYear === activeSessionLabel ||\r\n    report.academicSession === activeSessionLabel;\r\n}\r\n\r\nfunction isAdminGenerated(report) {\r\n  if (report.generatedByAdmin === true) return true;\r\n  if (report.createdByRole && String(report.createdByRole).toLowerCase() === \"admin\") return true;\r\n  const cb = String(report.createdBy || \"\").toLowerCase();\r\n  return cb === \"admin\" || cb.includes(\"admin\");\r\n}\r\n\r\nonAuthStateChanged(auth, async (user) => {\r\n  if (!user) { window.location.href = \"#/index.html\"; return; }\r\n  currentAdminId = user.uid;\r\n  await loadAllReports();\r\n});\r\n\r\nwindow.loadAllReports = async () => {\r\n  if (!currentAdminId) return;\r\n  const tableBody = document.getElementById('tableBody');\r\n  tableBody.innerHTML = '<tr><td colspan=\"9\" class=\"loading\"><span class=\"spinner\"></span> Loading all reports...</td></tr>';\r\n  try {\r\n    await loadActiveSession();\r\n    await loadTermsAndLocks();\r\n    const q = query(collection(db, \"schools\", currentAdminId, \"reportCards\"), orderBy('createdAt', 'desc'));\r\n    const snapshot = await getDocs(q);\r\n    allReports = [];\r\n    snapshot.forEach((d) => {\r\n      const report = { id: d.id, ...d.data() };\r\n      if (reportBelongsToActiveSession(report)) allReports.push(report);\r\n    });\r\n    populateClassResultControls();\r\n    displayReports(allReports);\r\n    updateStats(allReports);\r\n  } catch (error) {\r\n    console.error(\"Load error:\", error);\r\n    tableBody.innerHTML = '<tr><td colspan=\"9\" class=\"empty-state\"><svg><use href=\"#i-alert\"/></svg><h3>Error loading reports</h3><p>' + (error.message || '') + '</p></td></tr>';\r\n  }\r\n};\r\n\r\nfunction getReportClass(report = {}) {\r\n  return String(report.student?.class || report.class || \"\").trim();\r\n}\r\n\r\nfunction getReportSection(report = {}) {\r\n  return String(report.student?.section || report.section || \"\").trim();\r\n}\r\n\r\nfunction populateClassResultControls() {\r\n  const classSelect = document.getElementById(\"classResultSelect\");\r\n  const sectionSelect = document.getElementById(\"sectionResultSelect\");\r\n  if (!classSelect || !sectionSelect) return;\r\n  const previousClass = classSelect.value;\r\n  const classes = Array.from(new Set(allReports.map(getReportClass).filter(Boolean)))\r\n    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));\r\n  classSelect.innerHTML = '<option value=\"\">All Classes</option>' +\r\n    classes.map(className => `<option value=\"${escapeHtml(className)}\">${escapeHtml(className)}</option>`).join(\"\");\r\n  classSelect.value = classes.includes(previousClass) ? previousClass : \"\";\r\n  populateClassResultSections();\r\n}\r\n\r\nwindow.populateClassResultSections = () => {\r\n  const classSelect = document.getElementById(\"classResultSelect\");\r\n  const sectionSelect = document.getElementById(\"sectionResultSelect\");\r\n  if (!classSelect || !sectionSelect) return;\r\n  const selectedClass = classSelect.value;\r\n  const previousSection = sectionSelect.value;\r\n  const sections = Array.from(new Set(\r\n    allReports\r\n      .filter(report => !selectedClass || getReportClass(report) === selectedClass)\r\n      .map(getReportSection)\r\n      .filter(Boolean)\r\n  )).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));\r\n  sectionSelect.innerHTML = '<option value=\"\">All Sections</option>' +\r\n    sections.map(section => `<option value=\"${escapeHtml(section)}\">${escapeHtml(section)}</option>`).join(\"\");\r\n  sectionSelect.value = sections.includes(previousSection) ? previousSection : \"\";\r\n};\r\n\r\nwindow.showClassWiseResults = () => {\r\n  const selectedClass = document.getElementById(\"classResultSelect\")?.value || \"\";\r\n  const selectedSection = document.getElementById(\"sectionResultSelect\")?.value || \"\";\r\n  const filtered = allReports.filter(report => {\r\n    const classMatch = !selectedClass || getReportClass(report) === selectedClass;\r\n    const sectionMatch = !selectedSection || getReportSection(report) === selectedSection;\r\n    return classMatch && sectionMatch;\r\n  });\r\n  document.getElementById(\"searchClass\").value = selectedClass\r\n    ? `${selectedClass}${selectedSection ? `-${selectedSection}` : \"\"}`\r\n    : \"\";\r\n  document.getElementById(\"searchName\").value = \"\";\r\n  document.getElementById(\"searchStudentId\").value = \"\";\r\n  document.getElementById(\"gradeFilter\").value = \"\";\r\n  displayReports(filtered);\r\n  updateStats(filtered);\r\n};\r\n\r\nfunction escapeHtml(s) {\r\n  return String(s ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\r\n}\r\n\r\nwindow.displayReports = (reports) => {\r\n  const tableBody = document.getElementById('tableBody');\r\n  if (reports.length === 0) {\r\n    tableBody.innerHTML = '<tr><td colspan=\"9\"><div class=\"empty-state\"><svg><use href=\"#i-empty\"/></svg><h3>No Reports Found</h3><p>No report cards match your criteria</p></div></td></tr>';\r\n    return;\r\n  }\r\n  tableBody.innerHTML = '';\r\n  reports.forEach(report => {\r\n    const studentName = report.student?.name || 'N/A';\r\n    const studentId = report.student?.studentId || 'N/A';\r\n    const classInfo = `${report.student?.class || '-'}-${report.student?.section || '-'}`;\r\n    const percentage = report.percentage ? Number(report.percentage).toFixed(1) : 0;\r\n    const grade = report.grade || 'N/A';\r\n    const termLabel = report.termLabel || report.term || getTermLabel(getReportTermKey(report)) || 'N/A';\r\n    const date = report.createdAt?.toDate ? new Date(report.createdAt.toDate()).toLocaleDateString('en-IN') : 'N/A';\r\n    const gradeClass = 'grade-' + String(grade).toLowerCase();\r\n    const percentageClass = percentage >= 75 ? 'high' : percentage >= 40 ? 'medium' : 'low';\r\n    const generatedBy = isAdminGenerated(report)\r\n      ? `<span class=\"admin-badge\"><svg class=\"icon-sm\"><use href=\"#i-crown\"/></svg> Admin Generated</span>`\r\n      : `<span class=\"teacher-badge\"><svg class=\"icon-sm\"><use href=\"#i-user\"/></svg> ${escapeHtml(report.createdBy || 'Teacher')}</span>`;\r\n\r\n    const row = document.createElement('tr');\r\n    row.innerHTML = `\r\n      <td><div class=\"student-cell\">${escapeHtml(studentName)}</div></td>\r\n      <td><span class=\"student-id\">${escapeHtml(studentId)}</span></td>\r\n      <td>${escapeHtml(classInfo)}</td>\r\n      <td><span class=\"percentage ${percentageClass}\">${percentage}%</span></td>\r\n      <td><span class=\"grade-badge ${gradeClass}\">${escapeHtml(grade)}</span></td>\r\n      <td>${escapeHtml(termLabel)}</td>\r\n      <td>${generatedBy}</td>\r\n      <td>${date}</td>\r\n      <td>\r\n        <div class=\"actions\">\r\n          <button class=\"action-btn view\" onclick=\"viewReport('${report.id}')\"><svg class=\"icon-sm\"><use href=\"#i-eye\"/></svg> View</button>\r\n          <button class=\"action-btn edit\" onclick=\"editReport('${report.id}')\"><svg class=\"icon-sm\"><use href=\"#i-clipboard\"/></svg> Edit</button>\r\n          <button class=\"action-btn print\" onclick=\"printReport('${report.id}')\"><svg class=\"icon-sm\"><use href=\"#i-print\"/></svg> Print</button>\r\n          <button class=\"action-btn delete\" onclick=\"deleteReportCard('${report.id}', '${escapeHtml(studentName).replace(/'/g,\"\\\\'\")}')\"><svg class=\"icon-sm\"><use href=\"#i-trash\"/></svg> Delete</button>\r\n        </div>\r\n      </td>`;\r\n    tableBody.appendChild(row);\r\n  });\r\n};\r\n\r\nwindow.updateStats = (reports) => {\r\n  const total = reports.length;\r\n  const grid = document.getElementById('statsGrid');\r\n  if (total === 0) { grid.style.display = 'none'; return; }\r\n  const avgPercentage = reports.reduce((s, r) => s + (Number(r.percentage) || 0), 0) / total;\r\n  const passedCount = reports.filter(r => (Number(r.percentage) || 0) >= 40).length;\r\n  const aPlusCount = reports.filter(r => r.grade === 'A+').length;\r\n  grid.style.display = 'grid';\r\n  document.getElementById('totalReports').textContent = total;\r\n  document.getElementById('avgPercentage').textContent = avgPercentage.toFixed(1) + '%';\r\n  document.getElementById('passedCount').textContent = passedCount;\r\n  document.getElementById('aPlusCount').textContent = aPlusCount;\r\n};\r\n\r\nwindow.applyFilters = () => {\r\n  const searchName = document.getElementById('searchName').value.toLowerCase();\r\n  const searchStudentId = document.getElementById('searchStudentId').value.toLowerCase();\r\n  const searchClass = document.getElementById('searchClass').value.toUpperCase();\r\n  const gradeFilter = document.getElementById('gradeFilter').value;\r\n  const termFilter = document.getElementById('termFilter').value;\r\n  const filtered = allReports.filter(report => {\r\n    const nameMatch = !searchName || (report.student?.name || '').toLowerCase().includes(searchName);\r\n    const studentIdMatch = !searchStudentId || String(report.student?.studentId || report.studentId || '').toLowerCase().includes(searchStudentId);\r\n    const classMatch = !searchClass || `${report.student?.class || ''}-${report.student?.section || ''}`.toUpperCase().includes(searchClass);\r\n    const gradeMatch = !gradeFilter || report.grade === gradeFilter;\r\n    const termMatch = !termFilter || getReportTermKey(report) === termFilter;\r\n    return nameMatch && studentIdMatch && classMatch && gradeMatch && termMatch;\r\n  });\r\n  displayReports(filtered);\r\n  updateStats(filtered);\r\n};\r\n\r\nwindow.resetFilters = () => {\r\n  document.getElementById('searchName').value = '';\r\n  document.getElementById('searchStudentId').value = '';\r\n  document.getElementById('searchClass').value = '';\r\n  document.getElementById('gradeFilter').value = '';\r\n  document.getElementById('termFilter').value = '';\r\n  displayReports(allReports);\r\n  updateStats(allReports);\r\n};\r\n\r\nwindow.viewReport = (reportId) => {\r\n  const report = allReports.find(r => r.id === reportId);\r\n  if (!report) return alert('Report not found');\r\n  const percentage = report.percentage ? Number(report.percentage).toFixed(1) : 0;\r\n  const subjectsHtml = (report.subjects || []).map(sub => `\r\n    <tr><td>${escapeHtml(sub.name)}</td><td>${escapeHtml(sub.obtained)} / ${escapeHtml(sub.maxMarks)}</td></tr>`).join('');\r\n  const genBadge = isAdminGenerated(report)\r\n    ? `<span class=\"admin-badge\"><svg class=\"icon-sm\"><use href=\"#i-crown\"/></svg> Admin Generated</span>`\r\n    : `<span class=\"teacher-badge\"><svg class=\"icon-sm\"><use href=\"#i-user\"/></svg> ${escapeHtml(report.createdBy || 'Teacher')}</span>`;\r\n\r\n  document.getElementById('modalBody').innerHTML = `\r\n    <div class=\"report-info\">\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Student Name</span><span class=\"report-info-value\">${escapeHtml(report.student?.name || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Student ID</span><span class=\"report-info-value\">${escapeHtml(report.student?.studentId || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Class</span><span class=\"report-info-value\">${escapeHtml(report.student?.class || 'N/A')}-${escapeHtml(report.student?.section || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Grade</span><span class=\"report-info-value\">${escapeHtml(report.grade || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Percentage</span><span class=\"report-info-value\">${percentage}%</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Generated By</span><span class=\"report-info-value\">${genBadge}</span></div>\r\n    </div>\r\n    <h3 class=\"section-title\" style=\"font-size:16px;\">Subject Marks</h3>\r\n    <table class=\"subjects-table\">\r\n      <thead><tr><th>Subject</th><th>Marks</th></tr></thead>\r\n      <tbody>${subjectsHtml || '<tr><td colspan=\"2\" style=\"text-align:center;color:#718096;\">No subjects</td></tr>'}</tbody>\r\n    </table>`;\r\n  document.getElementById('reportModal').style.display = 'block';\r\n};\r\n\r\nfunction getReportGrade(percentage) {\r\n  const pct = Number(percentage || 0);\r\n  if (pct >= 90) return \"A+\";\r\n  if (pct >= 75) return \"A\";\r\n  if (pct >= 60) return \"B\";\r\n  if (pct >= 40) return \"C\";\r\n  return \"F\";\r\n}\r\n\r\nfunction getReportMarksTermKey(report = {}) {\r\n  const termKey = getReportTermKey(report);\r\n  return report.sessionId ? `${report.sessionId}__${termKey}` : termKey;\r\n}\r\n\r\nwindow.editReport = (reportId) => {\r\n  const report = allReports.find(r => r.id === reportId);\r\n  if (!report) return alert('Report not found');\r\n  const subjects = report.subjects || [];\r\n  const rows = subjects.map((sub, index) => `\r\n    <div class=\"edit-row\">\r\n      <div>\r\n        <strong>${escapeHtml(sub.name || `Subject ${index + 1}`)}</strong><br>\r\n        <small>Max marks: ${escapeHtml(sub.maxMarks || 100)}</small>\r\n      </div>\r\n      <input class=\"admin-mark-input\" data-index=\"${index}\" data-subject=\"${escapeHtml(sub.name || '')}\" type=\"number\" min=\"0\" max=\"${escapeHtml(sub.maxMarks || 100)}\" value=\"${escapeHtml(sub.obtained ?? 0)}\">\r\n      <input class=\"admin-max-input\" data-index=\"${index}\" type=\"number\" min=\"1\" value=\"${escapeHtml(sub.maxMarks || 100)}\">\r\n    </div>\r\n  `).join('');\r\n\r\n  document.getElementById('modalBody').innerHTML = `\r\n    <div class=\"report-info\">\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Student</span><span class=\"report-info-value\">${escapeHtml(report.student?.name || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Student ID</span><span class=\"report-info-value\">${escapeHtml(report.student?.studentId || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Term</span><span class=\"report-info-value\">${escapeHtml(report.termLabel || report.term || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Lock Status</span><span class=\"report-info-value\">${isTermLocked(getReportTermKey(report)) ? 'Locked for teachers' : 'Unlocked'}</span></div>\r\n    </div>\r\n    <h3 class=\"section-title\" style=\"font-size:16px;\">Admin Edit Marks</h3>\r\n    <div class=\"edit-grid\">${rows || '<div class=\"empty-state\">No subjects found in this report.</div>'}</div>\r\n    <div style=\"display:flex;gap:10px;justify-content:flex-end;margin-top:22px;flex-wrap:wrap;\">\r\n      <button class=\"secondary\" onclick=\"viewReport('${report.id}')\">Cancel</button>\r\n      <button class=\"primary\" onclick=\"saveReportEdits('${report.id}')\"><svg class=\"icon\"><use href=\"#i-check\"/></svg> Save Marks</button>\r\n    </div>\r\n  `;\r\n  document.getElementById('reportModal').style.display = 'block';\r\n};\r\n\r\nwindow.saveReportEdits = async (reportId) => {\r\n  const report = allReports.find(r => r.id === reportId);\r\n  if (!report) return alert('Report not found');\r\n  const marks = Array.from(document.querySelectorAll('.admin-mark-input'));\r\n  const maxInputs = Array.from(document.querySelectorAll('.admin-max-input'));\r\n  const previousSubjects = report.subjects || [];\r\n  let total = 0;\r\n  let totalMax = 0;\r\n  const updatedSubjects = previousSubjects.map((sub, index) => {\r\n    const obtained = Number(marks.find(input => Number(input.dataset.index) === index)?.value || 0);\r\n    const maxMarks = Math.max(1, Number(maxInputs.find(input => Number(input.dataset.index) === index)?.value || sub.maxMarks || 100));\r\n    total += obtained;\r\n    totalMax += maxMarks;\r\n    return { ...sub, obtained, maxMarks };\r\n  });\r\n  const percentage = totalMax ? Math.round((total / totalMax) * 100) : 0;\r\n  const grade = getReportGrade(percentage);\r\n  const studentId = report.student?.studentId || report.studentId;\r\n  const marksTermKey = getReportMarksTermKey(report);\r\n\r\n  try {\r\n    await setDoc(doc(db, \"schools\", currentAdminId, \"reportCards\", reportId), {\r\n      subjects: updatedSubjects,\r\n      totalMarks: total,\r\n      totalMaxMarks: totalMax,\r\n      percentage,\r\n      grade,\r\n      generatedByAdmin: true,\r\n      editedByAdmin: true,\r\n      updatedAt: new Date(),\r\n      updatedBy: auth.currentUser?.uid || \"admin\"\r\n    }, { merge: true });\r\n\r\n    if (studentId && marksTermKey) {\r\n      const marksPayload = {};\r\n      updatedSubjects.forEach((sub) => {\r\n        if (!sub.name) return;\r\n        marksPayload[sub.name] = {\r\n          obtained: Number(sub.obtained || 0),\r\n          maxMarks: Number(sub.maxMarks || 100)\r\n        };\r\n      });\r\n      await setDoc(doc(db, \"schools\", currentAdminId, \"marks\", studentId), {\r\n        terms: { [marksTermKey]: marksPayload },\r\n        updatedAt: new Date(),\r\n        updatedBy: auth.currentUser?.uid || \"admin\",\r\n        updatedByRole: \"admin\"\r\n      }, { merge: true });\r\n    }\r\n\r\n    alert(\"Marks updated successfully.\");\r\n    await loadAllReports();\r\n    editReport(reportId);\r\n  } catch (error) {\r\n    console.error(\"Save marks error:\", error);\r\n    alert(\"Unable to save marks.\");\r\n  }\r\n};\r\n\r\nwindow.printReport = (reportId) => {\r\n  const report = allReports.find(r => r.id === reportId);\r\n  if (!report) return alert('Report not found');\r\n  const percentage = report.percentage ? Number(report.percentage).toFixed(1) : 0;\r\n  const genLabel = isAdminGenerated(report) ? 'Admin Generated' : (report.createdBy || 'Teacher');\r\n  const subjectsHtml = (report.subjects || []).map(sub => `\r\n    <tr><td>${escapeHtml(sub.name)}</td><td>${escapeHtml(sub.obtained)}</td><td>${escapeHtml(sub.maxMarks)}</td></tr>`).join('');\r\n  const w = window.open('', '_blank');\r\n  w.document.write(`<!DOCTYPE html><html><head>\r\n<title>Report Card</title>\r\n    <style>\r\n      body{font-family:Segoe UI,sans-serif;padding:40px;color:#2d3748;}\r\n      .rc{max-width:800px;margin:0 auto;border:2px solid #667eea;border-radius:12px;padding:30px;}\r\n      h1{text-align:center;color:#667eea;margin:0 0 5px;}\r\n      .sub{text-align:center;color:#718096;margin-bottom:25px;}\r\n      .info{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-bottom:25px;padding:15px;background:#f7fafc;border-radius:8px;}\r\n      .info div{font-size:14px;} .info b{color:#4a5568;display:block;font-size:11px;text-transform:uppercase;margin-bottom:3px;}\r\n      table{width:100%;border-collapse:collapse;margin:15px 0;}\r\n      th,td{padding:10px;border:1px solid #e2e8f0;text-align:left;}\r\n      th{background:#667eea;color:white;}\r\n      .totals{display:flex;justify-content:space-around;padding:20px;background:#f0f4ff;border-radius:8px;margin-top:20px;}\r\n      .totals div{text-align:center;} .totals b{display:block;font-size:24px;color:#667eea;}\r\n      .foot{text-align:center;margin-top:30px;font-size:12px;color:#718096;}\r\n      @media print{body{padding:0;} .rc{border:none;}}\r\n    </style></head><body>\r\n    <div class=\"rc\">\r\n      <h1>Student Report Card</h1>\r\n      <p class=\"sub\">Academic Performance Report</p>\r\n      <div class=\"info\">\r\n        <div><b>Student Name</b>${escapeHtml(report.student?.name || 'N/A')}</div>\r\n        <div><b>Student ID</b>${escapeHtml(report.student?.studentId || 'N/A')}</div>\r\n        <div><b>Class</b>${escapeHtml(report.student?.class || 'N/A')}-${escapeHtml(report.student?.section || 'N/A')}</div>\r\n        <div><b>Generated By</b>${escapeHtml(genLabel)}</div>\r\n      </div>\r\n      <table>\r\n        <thead><tr><th>Subject</th><th>Marks Obtained</th><th>Max Marks</th></tr></thead>\r\n        <tbody>${subjectsHtml}</tbody>\r\n      </table>\r\n      <div class=\"totals\">\r\n        <div><b>${escapeHtml(report.grade || 'N/A')}</b>Overall Grade</div>\r\n        <div><b>${percentage}%</b>Percentage</div>\r\n      </div>\r\n      <p class=\"foot\">Generated on ${new Date().toLocaleDateString('en-IN',{year:'numeric',month:'long',day:'numeric'})}</p>\r\n    </div>\r\n    <script>window.onload=()=>window.print();<\\/script>","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\r\nhtml.sx-page-loading,\r\nhtml.sx-page-loading body {\r\n  min-height: 100%;\r\n  background: #f8fafc !important;\r\n}\r\nhtml.sx-page-loading body::before,\r\nhtml.sx-page-loading body::after {\r\n  visibility: hidden !important;\r\n}\r\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\r\n  visibility: hidden !important;\r\n}\r\n.sx-page-loader {\r\n  position: fixed;\r\n  inset: 0;\r\n  z-index: 2147482500;\r\n  display: flex;\r\n  align-items: stretch;\r\n  justify-content: stretch;\r\n  background: #f8fafc;\r\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\r\n  overflow: hidden;\r\n}\r\n.sx-page-loader.is-hidden {\r\n  opacity: 0;\r\n  visibility: hidden;\r\n  pointer-events: none;\r\n}\r\n.sx-page-loader .dots-container {\r\n  position: fixed;\r\n  inset: 0;\r\n  display: block;\r\n  width: 100vw;\r\n  height: 100vh;\r\n  padding: 0;\r\n  margin: 0;\r\n  overflow: hidden;\r\n  background: #f8fafc;\r\n}\r\n.sx-page-loader .dots-container::before,\r\n.sx-page-loader .dots-container::after,\r\n.sx-page-loader .dot {\r\n  display: none !important;\r\n}\r\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"admin-shell.css?v=navbar-20260721"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{"type":"module"},"text":"\r\nimport { initializeApp } from \"./firebase-compat.js\";\r\nimport { getFirestore, collection, query, orderBy, getDocs, doc, getDoc, setDoc, deleteDoc } from \"./firebase-compat.js\";\r\nimport { getAuth, onAuthStateChanged } from \"./firebase-compat.js\";\r\n\r\nconst firebaseConfig = {\r\n  apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n  authDomain: \"schoolix-48107.firebaseapp.com\",\r\n  projectId: \"schoolix-48107\",\r\n  storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n  messagingSenderId: \"133937954491\",\r\n  appId: \"1:133937954491:web:69d8064422617eb8c4339e\",\r\n  measurementId: \"G-EG23XE5Q0Z\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst db = getFirestore(app);\r\nconst auth = getAuth(app);\r\nconst RESULT_NOTIFICATION_SEND_URL = \"https://ezkmeedcqetztkeppxil.supabase.co/functions/v1/send-app-notification\";\r\nconst RESULT_NOTIFICATION_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImV6a21lZWRjcWV0enRrZXBweGlsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzgxMjk5NjAsImV4cCI6MjA5MzcwNTk2MH0.1davJ_NYkFhHToUtcFBR0kA6dk0-cOkaIbK2SCObkQg\";\r\n\r\nlet allReports = [];\r\nlet allTerms = [];\r\nlet reportTermLocks = {};\r\nlet reportTermVisibility = {};\r\nlet currentAdminId = null;\r\nlet activeSessionId = \"\";\r\nlet activeSessionLabel = \"\";\r\nlet selectedLockTermKey = \"\";\r\nlet selectedLiveTermKey = \"\";\r\n\r\nasync function loadActiveSession() {\r\n  activeSessionId = \"\";\r\n  activeSessionLabel = \"\";\r\n  try {\r\n    let viewSessionId = \"\";\r\n    try { viewSessionId = localStorage.getItem(\"schoolix.viewSessionId\") || \"\"; } catch (_) {}\r\n    const activeSnap = await getDoc(doc(db, \"schools\", currentAdminId, \"settings\", \"activeSession\"));\r\n    activeSessionId = viewSessionId || (activeSnap.exists() ? activeSnap.data().sessionId || \"\" : \"\");\r\n    if (!activeSessionId) return;\r\n    const sessionSnap = await getDoc(doc(db, \"schools\", currentAdminId, \"sessions\", activeSessionId));\r\n    if (!sessionSnap.exists()) {\r\n      try { if (viewSessionId) localStorage.removeItem(\"schoolix.viewSessionId\"); } catch (_) {}\r\n      activeSessionId = activeSnap.exists() ? activeSnap.data().sessionId || \"\" : \"\";\r\n      if (!activeSessionId || activeSessionId === viewSessionId) return;\r\n      const fallbackSnap = await getDoc(doc(db, \"schools\", currentAdminId, \"sessions\", activeSessionId));\r\n      if (!fallbackSnap.exists()) return;\r\n      const fallbackData = fallbackSnap.data();\r\n      activeSessionLabel = fallbackData.session || fallbackData.name || \"\";\r\n      return;\r\n    }\r\n    const data = sessionSnap.data();\r\n    activeSessionLabel = data.session || data.name || \"\";\r\n  } catch (e) { console.error(\"Session load error:\", e); }\r\n}\r\n\r\nfunction normalizeTermKey(value) {\r\n  return String(value || \"\").trim().toLowerCase().replace(/[^a-z0-9]+/g, \"-\").replace(/^-+|-+$/g, \"\");\r\n}\r\n\r\nfunction getTermLabel(termKey) {\r\n  return allTerms.find((term) => term.termKey === termKey)?.label || termKey || \"Selected term\";\r\n}\r\n\r\nfunction getTermLockKey(termKey) {\r\n  if (!termKey) return \"\";\r\n  return activeSessionId ? `${activeSessionId}__${termKey}` : termKey;\r\n}\r\n\r\nfunction isTermLocked(termKey) {\r\n  return reportTermLocks[getTermLockKey(termKey)]?.locked === true;\r\n}\r\n\r\nfunction getTermVisibilityKey(termKey) {\r\n  return getTermLockKey(termKey);\r\n}\r\n\r\nfunction isTermLive(termKey) {\r\n  return reportTermVisibility[getTermVisibilityKey(termKey)]?.live === true;\r\n}\r\n\r\nasync function sendResultLiveNotification(termLabel) {\r\n  const token = await auth.currentUser?.getIdToken(true);\r\n  if (!token) return;\r\n  const response = await fetch(RESULT_NOTIFICATION_SEND_URL, {\r\n    method: \"POST\",\r\n    headers: {\r\n      \"Content-Type\": \"application/json\",\r\n      \"apikey\": RESULT_NOTIFICATION_ANON_KEY,\r\n      \"Authorization\": `Bearer ${RESULT_NOTIFICATION_ANON_KEY}`,\r\n      \"x-firebase-auth\": token\r\n    },\r\n    body: JSON.stringify({\r\n      title: \"Result is live\",\r\n      message: `${termLabel} result is now live. Students with cleared dues can view it in the app.`,\r\n      audience: \"students\"\r\n    })\r\n  });\r\n  if (!response.ok) throw new Error(await response.text());\r\n}\r\n\r\nfunction getReportTermKey(report = {}) {\r\n  return report.termKey || normalizeTermKey(report.termLabel || report.term || \"\");\r\n}\r\n\r\nasync function loadTermsAndLocks() {\r\n  allTerms = [];\r\n  reportTermLocks = {};\r\n  reportTermVisibility = {};\r\n  try {\r\n    const termSnap = await getDocs(collection(db, \"schools\", currentAdminId, \"terms\"));\r\n    const unique = new Map();\r\n    termSnap.docs\r\n      .map(d => ({ id: d.id, ...d.data() }))\r\n      .filter(term => {\r\n        if (!activeSessionId && !activeSessionLabel) return true;\r\n        if (!term.sessionId && !term.session && !term.currentYear && !term.academicSession) return true;\r\n        return term.sessionId === activeSessionId ||\r\n          term.session === activeSessionLabel ||\r\n          term.currentYear === activeSessionLabel ||\r\n          term.academicSession === activeSessionLabel;\r\n      })\r\n      .forEach(term => {\r\n        const termKey = term.termKey || normalizeTermKey(term.label || term.term || term.name || term.id);\r\n        if (!termKey) return;\r\n        unique.set(termKey, {\r\n          ...term,\r\n          termKey,\r\n          label: term.label || term.term || term.name || termKey\r\n        });\r\n      });\r\n    allTerms = Array.from(unique.values()).sort((a, b) => (a.createdAt?.seconds || 0) - (b.createdAt?.seconds || 0));\r\n\r\n    const lockSnap = await getDoc(doc(db, \"schools\", currentAdminId, \"settings\", \"reportCardTermLocks\"));\r\n    reportTermLocks = lockSnap.exists() ? (lockSnap.data().locks || {}) : {};\r\n    const visibilitySnap = await getDoc(doc(db, \"schools\", currentAdminId, \"settings\", \"reportCardTermVisibility\"));\r\n    reportTermVisibility = visibilitySnap.exists() ? (visibilitySnap.data().terms || {}) : {};\r\n  } catch (e) { console.error(\"Term lock load error:\", e); }\r\n  populateTermControls();\r\n  updateTermLockUI();\r\n  updateTermLiveUI();\r\n}\r\n\r\nfunction populateTermControls() {\r\n  const lockSelect = document.getElementById(\"termLockSelect\");\r\n  const liveSelect = document.getElementById(\"termLiveSelect\");\r\n  const filterSelect = document.getElementById(\"termFilter\");\r\n  if (lockSelect) {\r\n    lockSelect.innerHTML = allTerms.length\r\n      ? allTerms.map(term => `<option value=\"${escapeHtml(term.termKey)}\">${escapeHtml(term.label)}</option>`).join(\"\")\r\n      : '<option value=\"\">No terms found</option>';\r\n    if (!selectedLockTermKey || !allTerms.some(term => term.termKey === selectedLockTermKey)) {\r\n      selectedLockTermKey = allTerms[0]?.termKey || \"\";\r\n    }\r\n    lockSelect.value = selectedLockTermKey;\r\n  }\r\n  if (liveSelect) {\r\n    liveSelect.innerHTML = allTerms.length\r\n      ? allTerms.map(term => `<option value=\"${escapeHtml(term.termKey)}\">${escapeHtml(term.label)}</option>`).join(\"\")\r\n      : '<option value=\"\">No terms found</option>';\r\n    if (!selectedLiveTermKey || !allTerms.some(term => term.termKey === selectedLiveTermKey)) {\r\n      selectedLiveTermKey = selectedLockTermKey || allTerms[0]?.termKey || \"\";\r\n    }\r\n    liveSelect.value = selectedLiveTermKey;\r\n  }\r\n  if (filterSelect) {\r\n    const current = filterSelect.value;\r\n    filterSelect.innerHTML = '<option value=\"\">All Terms</option>' +\r\n      allTerms.map(term => `<option value=\"${escapeHtml(term.termKey)}\">${escapeHtml(term.label)}</option>`).join(\"\");\r\n    filterSelect.value = allTerms.some(term => term.termKey === current) ? current : \"\";\r\n  }\r\n}\r\n\r\nfunction updateTermLockUI() {\r\n  const btn = document.getElementById(\"termLockToggleBtn\");\r\n  const btnText = document.getElementById(\"termLockToggleText\");\r\n  const btnIcon = btn?.querySelector(\"svg use\");\r\n  const status = document.getElementById(\"termLockStatus\");\r\n  const statusText = status?.querySelector(\"span\");\r\n  const statusIcon = status?.querySelector(\"svg use\");\r\n  const banner = document.getElementById(\"lockBanner\");\r\n  const locked = isTermLocked(selectedLockTermKey);\r\n\r\n  if (!selectedLockTermKey) {\r\n    if (btn) btn.disabled = true;\r\n    if (statusText) statusText.textContent = \"No term\";\r\n    if (banner) banner.classList.remove(\"show\");\r\n    return;\r\n  }\r\n  if (btn) btn.disabled = false;\r\n  if (locked) {\r\n    btn.classList.remove(\"danger\"); btn.classList.add(\"success\");\r\n    btnText.textContent = \"Unlock Term\";\r\n    btnIcon?.setAttribute(\"href\", \"#i-unlock\");\r\n    status.classList.remove(\"unlocked\"); status.classList.add(\"locked\");\r\n    statusText.textContent = \"Locked\";\r\n    statusIcon?.setAttribute(\"href\", \"#i-lock\");\r\n    banner.classList.add(\"show\");\r\n  } else {\r\n    btn.classList.remove(\"success\"); btn.classList.add(\"danger\");\r\n    btnText.textContent = \"Lock Term\";\r\n    btnIcon?.setAttribute(\"href\", \"#i-lock\");\r\n    status.classList.remove(\"locked\"); status.classList.add(\"unlocked\");\r\n    statusText.textContent = \"Unlocked\";\r\n    statusIcon?.setAttribute(\"href\", \"#i-unlock\");\r\n    banner.classList.remove(\"show\");\r\n  }\r\n}\r\n\r\nwindow.onTermLockSelectChange = () => {\r\n  selectedLockTermKey = document.getElementById(\"termLockSelect\").value;\r\n  updateTermLockUI();\r\n};\r\n\r\nwindow.toggleSelectedTermLock = async () => {\r\n  if (!currentAdminId) return;\r\n  if (!selectedLockTermKey) return alert(\"Select a term first.\");\r\n  const newState = !isTermLocked(selectedLockTermKey);\r\n  const label = getTermLabel(selectedLockTermKey);\r\n  const msg = newState\r\n    ? `Lock report cards for ${label}?\\n\\nTeachers will NOT be able to edit marks or regenerate report cards for this term. Admin can still edit from this page.`\r\n    : `Unlock report cards for ${label}?\\n\\nTeachers will be able to edit marks and regenerate report cards for this term again.`;\r\n  if (!confirm(msg)) return;\r\n  try {\r\n    const lockKey = getTermLockKey(selectedLockTermKey);\r\n    reportTermLocks = {\r\n      ...reportTermLocks,\r\n      [lockKey]: {\r\n        locked: newState,\r\n        termKey: selectedLockTermKey,\r\n        termLabel: label,\r\n        sessionId: activeSessionId || \"\",\r\n        session: activeSessionLabel || \"\",\r\n        updatedAt: new Date(),\r\n        updatedBy: auth.currentUser?.uid || \"admin\"\r\n      }\r\n    };\r\n    await setDoc(doc(db, \"schools\", currentAdminId, \"settings\", \"reportCardTermLocks\"), {\r\n      locks: reportTermLocks,\r\n      updatedAt: new Date(),\r\n      updatedBy: auth.currentUser?.uid || \"admin\"\r\n    }, { merge: true });\r\n    updateTermLockUI();\r\n    alert(newState ? `${label} locked successfully.` : `${label} unlocked successfully.`);\r\n  } catch (e) {\r\n    console.error(e);\r\n    alert(\"Failed to update term lock.\");\r\n  }\r\n};\r\n\r\nfunction updateTermLiveUI() {\r\n  const btn = document.getElementById(\"termLiveToggleBtn\");\r\n  const btnText = document.getElementById(\"termLiveToggleText\");\r\n  const btnIcon = btn?.querySelector(\"svg use\");\r\n  const status = document.getElementById(\"termLiveStatus\");\r\n  const statusText = status?.querySelector(\"span\");\r\n  const statusIcon = status?.querySelector(\"svg use\");\r\n  const banner = document.getElementById(\"liveBanner\");\r\n  const live = isTermLive(selectedLiveTermKey);\r\n\r\n  if (!selectedLiveTermKey) {\r\n    if (btn) btn.disabled = true;\r\n    if (statusText) statusText.textContent = \"No term\";\r\n    if (banner) banner.classList.remove(\"show\");\r\n    return;\r\n  }\r\n  if (btn) btn.disabled = false;\r\n  if (live) {\r\n    btn.classList.remove(\"success\"); btn.classList.add(\"warning\");\r\n    btnText.textContent = \"Hide From Students\";\r\n    btnIcon?.setAttribute(\"href\", \"#i-lock\");\r\n    status.classList.remove(\"hidden\"); status.classList.add(\"live\");\r\n    statusText.textContent = \"Live\";\r\n    statusIcon?.setAttribute(\"href\", \"#i-eye\");\r\n    banner.classList.add(\"show\");\r\n  } else {\r\n    btn.classList.remove(\"warning\"); btn.classList.add(\"success\");\r\n    btnText.textContent = \"Make Live\";\r\n    btnIcon?.setAttribute(\"href\", \"#i-eye\");\r\n    status.classList.remove(\"live\"); status.classList.add(\"hidden\");\r\n    statusText.textContent = \"Hidden\";\r\n    statusIcon?.setAttribute(\"href\", \"#i-lock\");\r\n    banner.classList.remove(\"show\");\r\n  }\r\n}\r\n\r\nwindow.onTermLiveSelectChange = () => {\r\n  selectedLiveTermKey = document.getElementById(\"termLiveSelect\").value;\r\n  updateTermLiveUI();\r\n};\r\n\r\nwindow.toggleSelectedTermLive = async () => {\r\n  if (!currentAdminId) return;\r\n  if (!selectedLiveTermKey) return alert(\"Select a term first.\");\r\n  const newState = !isTermLive(selectedLiveTermKey);\r\n  const label = getTermLabel(selectedLiveTermKey);\r\n  const msg = newState\r\n    ? `Make ${label} live?\\n\\nStudents with no pending dues will be able to view this term's result. Students with dues will stay locked.`\r\n    : `Hide ${label} from students?\\n\\nTeachers and admin can still see reports, but students will not see this term.`;\r\n  if (!confirm(msg)) return;\r\n  try {\r\n    const visibilityKey = getTermVisibilityKey(selectedLiveTermKey);\r\n    reportTermVisibility = {\r\n      ...reportTermVisibility,\r\n      [visibilityKey]: {\r\n        live: newState,\r\n        termKey: selectedLiveTermKey,\r\n        termLabel: label,\r\n        sessionId: activeSessionId || \"\",\r\n        session: activeSessionLabel || \"\",\r\n        updatedAt: new Date(),\r\n        updatedBy: auth.currentUser?.uid || \"admin\"\r\n      }\r\n    };\r\n    await setDoc(doc(db, \"schools\", currentAdminId, \"settings\", \"reportCardTermVisibility\"), {\r\n      terms: reportTermVisibility,\r\n      updatedAt: new Date(),\r\n      updatedBy: auth.currentUser?.uid || \"admin\"\r\n    }, { merge: true });\r\n    if (newState) {\r\n      try {\r\n        await sendResultLiveNotification(label);\r\n      } catch (notificationError) {\r\n        console.warn(\"Result live notification failed\", notificationError);\r\n      }\r\n    }\r\n    updateTermLiveUI();\r\n    alert(newState ? `${label} is now live for eligible students.` : `${label} is now hidden from students.`);\r\n  } catch (e) {\r\n    console.error(e);\r\n    alert(\"Failed to update result visibility.\");\r\n  }\r\n};\r\n\r\nfunction reportBelongsToActiveSession(report) {\r\n  if (!activeSessionId && !activeSessionLabel) return true;\r\n  if (!report.sessionId && !report.session && !report.currentYear && !report.academicSession) return false;\r\n  return report.sessionId === activeSessionId ||\r\n    report.session === activeSessionLabel ||\r\n    report.currentYear === activeSessionLabel ||\r\n    report.academicSession === activeSessionLabel;\r\n}\r\n\r\nfunction isAdminGenerated(report) {\r\n  if (report.generatedByAdmin === true) return true;\r\n  if (report.createdByRole && String(report.createdByRole).toLowerCase() === \"admin\") return true;\r\n  const cb = String(report.createdBy || \"\").toLowerCase();\r\n  return cb === \"admin\" || cb.includes(\"admin\");\r\n}\r\n\r\nonAuthStateChanged(auth, async (user) => {\r\n  if (!user) { window.location.href = \"#/index.html\"; return; }\r\n  currentAdminId = user.uid;\r\n  await loadAllReports();\r\n});\r\n\r\nwindow.loadAllReports = async () => {\r\n  if (!currentAdminId) return;\r\n  const tableBody = document.getElementById('tableBody');\r\n  tableBody.innerHTML = '<tr><td colspan=\"9\" class=\"loading\"><span class=\"spinner\"></span> Loading all reports...</td></tr>';\r\n  try {\r\n    await loadActiveSession();\r\n    await loadTermsAndLocks();\r\n    const q = query(collection(db, \"schools\", currentAdminId, \"reportCards\"), orderBy('createdAt', 'desc'));\r\n    const snapshot = await getDocs(q);\r\n    allReports = [];\r\n    snapshot.forEach((d) => {\r\n      const report = { id: d.id, ...d.data() };\r\n      if (reportBelongsToActiveSession(report)) allReports.push(report);\r\n    });\r\n    populateClassResultControls();\r\n    displayReports(allReports);\r\n    updateStats(allReports);\r\n  } catch (error) {\r\n    console.error(\"Load error:\", error);\r\n    tableBody.innerHTML = '<tr><td colspan=\"9\" class=\"empty-state\"><svg><use href=\"#i-alert\"/></svg><h3>Error loading reports</h3><p>' + (error.message || '') + '</p></td></tr>';\r\n  }\r\n};\r\n\r\nfunction getReportClass(report = {}) {\r\n  return String(report.student?.class || report.class || \"\").trim();\r\n}\r\n\r\nfunction getReportSection(report = {}) {\r\n  return String(report.student?.section || report.section || \"\").trim();\r\n}\r\n\r\nfunction populateClassResultControls() {\r\n  const classSelect = document.getElementById(\"classResultSelect\");\r\n  const sectionSelect = document.getElementById(\"sectionResultSelect\");\r\n  if (!classSelect || !sectionSelect) return;\r\n  const previousClass = classSelect.value;\r\n  const classes = Array.from(new Set(allReports.map(getReportClass).filter(Boolean)))\r\n    .sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));\r\n  classSelect.innerHTML = '<option value=\"\">All Classes</option>' +\r\n    classes.map(className => `<option value=\"${escapeHtml(className)}\">${escapeHtml(className)}</option>`).join(\"\");\r\n  classSelect.value = classes.includes(previousClass) ? previousClass : \"\";\r\n  populateClassResultSections();\r\n}\r\n\r\nwindow.populateClassResultSections = () => {\r\n  const classSelect = document.getElementById(\"classResultSelect\");\r\n  const sectionSelect = document.getElementById(\"sectionResultSelect\");\r\n  if (!classSelect || !sectionSelect) return;\r\n  const selectedClass = classSelect.value;\r\n  const previousSection = sectionSelect.value;\r\n  const sections = Array.from(new Set(\r\n    allReports\r\n      .filter(report => !selectedClass || getReportClass(report) === selectedClass)\r\n      .map(getReportSection)\r\n      .filter(Boolean)\r\n  )).sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));\r\n  sectionSelect.innerHTML = '<option value=\"\">All Sections</option>' +\r\n    sections.map(section => `<option value=\"${escapeHtml(section)}\">${escapeHtml(section)}</option>`).join(\"\");\r\n  sectionSelect.value = sections.includes(previousSection) ? previousSection : \"\";\r\n};\r\n\r\nwindow.showClassWiseResults = () => {\r\n  const selectedClass = document.getElementById(\"classResultSelect\")?.value || \"\";\r\n  const selectedSection = document.getElementById(\"sectionResultSelect\")?.value || \"\";\r\n  const filtered = allReports.filter(report => {\r\n    const classMatch = !selectedClass || getReportClass(report) === selectedClass;\r\n    const sectionMatch = !selectedSection || getReportSection(report) === selectedSection;\r\n    return classMatch && sectionMatch;\r\n  });\r\n  document.getElementById(\"searchClass\").value = selectedClass\r\n    ? `${selectedClass}${selectedSection ? `-${selectedSection}` : \"\"}`\r\n    : \"\";\r\n  document.getElementById(\"searchName\").value = \"\";\r\n  document.getElementById(\"searchStudentId\").value = \"\";\r\n  document.getElementById(\"gradeFilter\").value = \"\";\r\n  displayReports(filtered);\r\n  updateStats(filtered);\r\n};\r\n\r\nfunction escapeHtml(s) {\r\n  return String(s ?? '').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\r\n}\r\n\r\nwindow.displayReports = (reports) => {\r\n  const tableBody = document.getElementById('tableBody');\r\n  if (reports.length === 0) {\r\n    tableBody.innerHTML = '<tr><td colspan=\"9\"><div class=\"empty-state\"><svg><use href=\"#i-empty\"/></svg><h3>No Reports Found</h3><p>No report cards match your criteria</p></div></td></tr>';\r\n    return;\r\n  }\r\n  tableBody.innerHTML = '';\r\n  reports.forEach(report => {\r\n    const studentName = report.student?.name || 'N/A';\r\n    const studentId = report.student?.studentId || 'N/A';\r\n    const classInfo = `${report.student?.class || '-'}-${report.student?.section || '-'}`;\r\n    const percentage = report.percentage ? Number(report.percentage).toFixed(1) : 0;\r\n    const grade = report.grade || 'N/A';\r\n    const termLabel = report.termLabel || report.term || getTermLabel(getReportTermKey(report)) || 'N/A';\r\n    const date = report.createdAt?.toDate ? new Date(report.createdAt.toDate()).toLocaleDateString('en-IN') : 'N/A';\r\n    const gradeClass = 'grade-' + String(grade).toLowerCase();\r\n    const percentageClass = percentage >= 75 ? 'high' : percentage >= 40 ? 'medium' : 'low';\r\n    const generatedBy = isAdminGenerated(report)\r\n      ? `<span class=\"admin-badge\"><svg class=\"icon-sm\"><use href=\"#i-crown\"/></svg> Admin Generated</span>`\r\n      : `<span class=\"teacher-badge\"><svg class=\"icon-sm\"><use href=\"#i-user\"/></svg> ${escapeHtml(report.createdBy || 'Teacher')}</span>`;\r\n\r\n    const row = document.createElement('tr');\r\n    row.innerHTML = `\r\n      <td><div class=\"student-cell\">${escapeHtml(studentName)}</div></td>\r\n      <td><span class=\"student-id\">${escapeHtml(studentId)}</span></td>\r\n      <td>${escapeHtml(classInfo)}</td>\r\n      <td><span class=\"percentage ${percentageClass}\">${percentage}%</span></td>\r\n      <td><span class=\"grade-badge ${gradeClass}\">${escapeHtml(grade)}</span></td>\r\n      <td>${escapeHtml(termLabel)}</td>\r\n      <td>${generatedBy}</td>\r\n      <td>${date}</td>\r\n      <td>\r\n        <div class=\"actions\">\r\n          <button class=\"action-btn view\" onclick=\"viewReport('${report.id}')\"><svg class=\"icon-sm\"><use href=\"#i-eye\"/></svg> View</button>\r\n          <button class=\"action-btn edit\" onclick=\"editReport('${report.id}')\"><svg class=\"icon-sm\"><use href=\"#i-clipboard\"/></svg> Edit</button>\r\n          <button class=\"action-btn print\" onclick=\"printReport('${report.id}')\"><svg class=\"icon-sm\"><use href=\"#i-print\"/></svg> Print</button>\r\n          <button class=\"action-btn delete\" onclick=\"deleteReportCard('${report.id}', '${escapeHtml(studentName).replace(/'/g,\"\\\\'\")}')\"><svg class=\"icon-sm\"><use href=\"#i-trash\"/></svg> Delete</button>\r\n        </div>\r\n      </td>`;\r\n    tableBody.appendChild(row);\r\n  });\r\n};\r\n\r\nwindow.updateStats = (reports) => {\r\n  const total = reports.length;\r\n  const grid = document.getElementById('statsGrid');\r\n  if (total === 0) { grid.style.display = 'none'; return; }\r\n  const avgPercentage = reports.reduce((s, r) => s + (Number(r.percentage) || 0), 0) / total;\r\n  const passedCount = reports.filter(r => (Number(r.percentage) || 0) >= 40).length;\r\n  const aPlusCount = reports.filter(r => r.grade === 'A+').length;\r\n  grid.style.display = 'grid';\r\n  document.getElementById('totalReports').textContent = total;\r\n  document.getElementById('avgPercentage').textContent = avgPercentage.toFixed(1) + '%';\r\n  document.getElementById('passedCount').textContent = passedCount;\r\n  document.getElementById('aPlusCount').textContent = aPlusCount;\r\n};\r\n\r\nwindow.applyFilters = () => {\r\n  const searchName = document.getElementById('searchName').value.toLowerCase();\r\n  const searchStudentId = document.getElementById('searchStudentId').value.toLowerCase();\r\n  const searchClass = document.getElementById('searchClass').value.toUpperCase();\r\n  const gradeFilter = document.getElementById('gradeFilter').value;\r\n  const termFilter = document.getElementById('termFilter').value;\r\n  const filtered = allReports.filter(report => {\r\n    const nameMatch = !searchName || (report.student?.name || '').toLowerCase().includes(searchName);\r\n    const studentIdMatch = !searchStudentId || String(report.student?.studentId || report.studentId || '').toLowerCase().includes(searchStudentId);\r\n    const classMatch = !searchClass || `${report.student?.class || ''}-${report.student?.section || ''}`.toUpperCase().includes(searchClass);\r\n    const gradeMatch = !gradeFilter || report.grade === gradeFilter;\r\n    const termMatch = !termFilter || getReportTermKey(report) === termFilter;\r\n    return nameMatch && studentIdMatch && classMatch && gradeMatch && termMatch;\r\n  });\r\n  displayReports(filtered);\r\n  updateStats(filtered);\r\n};\r\n\r\nwindow.resetFilters = () => {\r\n  document.getElementById('searchName').value = '';\r\n  document.getElementById('searchStudentId').value = '';\r\n  document.getElementById('searchClass').value = '';\r\n  document.getElementById('gradeFilter').value = '';\r\n  document.getElementById('termFilter').value = '';\r\n  displayReports(allReports);\r\n  updateStats(allReports);\r\n};\r\n\r\nwindow.viewReport = (reportId) => {\r\n  const report = allReports.find(r => r.id === reportId);\r\n  if (!report) return alert('Report not found');\r\n  const percentage = report.percentage ? Number(report.percentage).toFixed(1) : 0;\r\n  const subjectsHtml = (report.subjects || []).map(sub => `\r\n    <tr><td>${escapeHtml(sub.name)}</td><td>${escapeHtml(sub.obtained)} / ${escapeHtml(sub.maxMarks)}</td></tr>`).join('');\r\n  const genBadge = isAdminGenerated(report)\r\n    ? `<span class=\"admin-badge\"><svg class=\"icon-sm\"><use href=\"#i-crown\"/></svg> Admin Generated</span>`\r\n    : `<span class=\"teacher-badge\"><svg class=\"icon-sm\"><use href=\"#i-user\"/></svg> ${escapeHtml(report.createdBy || 'Teacher')}</span>`;\r\n\r\n  document.getElementById('modalBody').innerHTML = `\r\n    <div class=\"report-info\">\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Student Name</span><span class=\"report-info-value\">${escapeHtml(report.student?.name || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Student ID</span><span class=\"report-info-value\">${escapeHtml(report.student?.studentId || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Class</span><span class=\"report-info-value\">${escapeHtml(report.student?.class || 'N/A')}-${escapeHtml(report.student?.section || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Grade</span><span class=\"report-info-value\">${escapeHtml(report.grade || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Percentage</span><span class=\"report-info-value\">${percentage}%</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Generated By</span><span class=\"report-info-value\">${genBadge}</span></div>\r\n    </div>\r\n    <h3 class=\"section-title\" style=\"font-size:16px;\">Subject Marks</h3>\r\n    <table class=\"subjects-table\">\r\n      <thead><tr><th>Subject</th><th>Marks</th></tr></thead>\r\n      <tbody>${subjectsHtml || '<tr><td colspan=\"2\" style=\"text-align:center;color:#718096;\">No subjects</td></tr>'}</tbody>\r\n    </table>`;\r\n  document.getElementById('reportModal').style.display = 'block';\r\n};\r\n\r\nfunction getReportGrade(percentage) {\r\n  const pct = Number(percentage || 0);\r\n  if (pct >= 90) return \"A+\";\r\n  if (pct >= 75) return \"A\";\r\n  if (pct >= 60) return \"B\";\r\n  if (pct >= 40) return \"C\";\r\n  return \"F\";\r\n}\r\n\r\nfunction getReportMarksTermKey(report = {}) {\r\n  const termKey = getReportTermKey(report);\r\n  return report.sessionId ? `${report.sessionId}__${termKey}` : termKey;\r\n}\r\n\r\nwindow.editReport = (reportId) => {\r\n  const report = allReports.find(r => r.id === reportId);\r\n  if (!report) return alert('Report not found');\r\n  const subjects = report.subjects || [];\r\n  const rows = subjects.map((sub, index) => `\r\n    <div class=\"edit-row\">\r\n      <div>\r\n        <strong>${escapeHtml(sub.name || `Subject ${index + 1}`)}</strong><br>\r\n        <small>Max marks: ${escapeHtml(sub.maxMarks || 100)}</small>\r\n      </div>\r\n      <input class=\"admin-mark-input\" data-index=\"${index}\" data-subject=\"${escapeHtml(sub.name || '')}\" type=\"number\" min=\"0\" max=\"${escapeHtml(sub.maxMarks || 100)}\" value=\"${escapeHtml(sub.obtained ?? 0)}\">\r\n      <input class=\"admin-max-input\" data-index=\"${index}\" type=\"number\" min=\"1\" value=\"${escapeHtml(sub.maxMarks || 100)}\">\r\n    </div>\r\n  `).join('');\r\n\r\n  document.getElementById('modalBody').innerHTML = `\r\n    <div class=\"report-info\">\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Student</span><span class=\"report-info-value\">${escapeHtml(report.student?.name || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Student ID</span><span class=\"report-info-value\">${escapeHtml(report.student?.studentId || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Term</span><span class=\"report-info-value\">${escapeHtml(report.termLabel || report.term || 'N/A')}</span></div>\r\n      <div class=\"report-info-item\"><span class=\"report-info-label\">Lock Status</span><span class=\"report-info-value\">${isTermLocked(getReportTermKey(report)) ? 'Locked for teachers' : 'Unlocked'}</span></div>\r\n    </div>\r\n    <h3 class=\"section-title\" style=\"font-size:16px;\">Admin Edit Marks</h3>\r\n    <div class=\"edit-grid\">${rows || '<div class=\"empty-state\">No subjects found in this report.</div>'}</div>\r\n    <div style=\"display:flex;gap:10px;justify-content:flex-end;margin-top:22px;flex-wrap:wrap;\">\r\n      <button class=\"secondary\" onclick=\"viewReport('${report.id}')\">Cancel</button>\r\n      <button class=\"primary\" onclick=\"saveReportEdits('${report.id}')\"><svg class=\"icon\"><use href=\"#i-check\"/></svg> Save Marks</button>\r\n    </div>\r\n  `;\r\n  document.getElementById('reportModal').style.display = 'block';\r\n};\r\n\r\nwindow.saveReportEdits = async (reportId) => {\r\n  const report = allReports.find(r => r.id === reportId);\r\n  if (!report) return alert('Report not found');\r\n  const marks = Array.from(document.querySelectorAll('.admin-mark-input'));\r\n  const maxInputs = Array.from(document.querySelectorAll('.admin-max-input'));\r\n  const previousSubjects = report.subjects || [];\r\n  let total = 0;\r\n  let totalMax = 0;\r\n  const updatedSubjects = previousSubjects.map((sub, index) => {\r\n    const obtained = Number(marks.find(input => Number(input.dataset.index) === index)?.value || 0);\r\n    const maxMarks = Math.max(1, Number(maxInputs.find(input => Number(input.dataset.index) === index)?.value || sub.maxMarks || 100));\r\n    total += obtained;\r\n    totalMax += maxMarks;\r\n    return { ...sub, obtained, maxMarks };\r\n  });\r\n  const percentage = totalMax ? Math.round((total / totalMax) * 100) : 0;\r\n  const grade = getReportGrade(percentage);\r\n  const studentId = report.student?.studentId || report.studentId;\r\n  const marksTermKey = getReportMarksTermKey(report);\r\n\r\n  try {\r\n    await setDoc(doc(db, \"schools\", currentAdminId, \"reportCards\", reportId), {\r\n      subjects: updatedSubjects,\r\n      totalMarks: total,\r\n      totalMaxMarks: totalMax,\r\n      percentage,\r\n      grade,\r\n      generatedByAdmin: true,\r\n      editedByAdmin: true,\r\n      updatedAt: new Date(),\r\n      updatedBy: auth.currentUser?.uid || \"admin\"\r\n    }, { merge: true });\r\n\r\n    if (studentId && marksTermKey) {\r\n      const marksPayload = {};\r\n      updatedSubjects.forEach((sub) => {\r\n        if (!sub.name) return;\r\n        marksPayload[sub.name] = {\r\n          obtained: Number(sub.obtained || 0),\r\n          maxMarks: Number(sub.maxMarks || 100)\r\n        };\r\n      });\r\n      await setDoc(doc(db, \"schools\", currentAdminId, \"marks\", studentId), {\r\n        terms: { [marksTermKey]: marksPayload },\r\n        updatedAt: new Date(),\r\n        updatedBy: auth.currentUser?.uid || \"admin\",\r\n        updatedByRole: \"admin\"\r\n      }, { merge: true });\r\n    }\r\n\r\n    alert(\"Marks updated successfully.\");\r\n    await loadAllReports();\r\n    editReport(reportId);\r\n  } catch (error) {\r\n    console.error(\"Save marks error:\", error);\r\n    alert(\"Unable to save marks.\");\r\n  }\r\n};\r\n\r\nwindow.printReport = (reportId) => {\r\n  const report = allReports.find(r => r.id === reportId);\r\n  if (!report) return alert('Report not found');\r\n  const percentage = report.percentage ? Number(report.percentage).toFixed(1) : 0;\r\n  const genLabel = isAdminGenerated(report) ? 'Admin Generated' : (report.createdBy || 'Teacher');\r\n  const subjectsHtml = (report.subjects || []).map(sub => `\r\n    <tr><td>${escapeHtml(sub.name)}</td><td>${escapeHtml(sub.obtained)}</td><td>${escapeHtml(sub.maxMarks)}</td></tr>`).join('');\r\n  const w = window.open('', '_blank');\r\n  w.document.write(`<!DOCTYPE html><html><head>\r\n<title>Report Card</title>\r\n    <style>\r\n      body{font-family:Segoe UI,sans-serif;padding:40px;color:#2d3748;}\r\n      .rc{max-width:800px;margin:0 auto;border:2px solid #667eea;border-radius:12px;padding:30px;}\r\n      h1{text-align:center;color:#667eea;margin:0 0 5px;}\r\n      .sub{text-align:center;color:#718096;margin-bottom:25px;}\r\n      .info{display:grid;grid-template-columns:1fr 1fr;gap:15px;margin-bottom:25px;padding:15px;background:#f7fafc;border-radius:8px;}\r\n      .info div{font-size:14px;} .info b{color:#4a5568;display:block;font-size:11px;text-transform:uppercase;margin-bottom:3px;}\r\n      table{width:100%;border-collapse:collapse;margin:15px 0;}\r\n      th,td{padding:10px;border:1px solid #e2e8f0;text-align:left;}\r\n      th{background:#667eea;color:white;}\r\n      .totals{display:flex;justify-content:space-around;padding:20px;background:#f0f4ff;border-radius:8px;margin-top:20px;}\r\n      .totals div{text-align:center;} .totals b{display:block;font-size:24px;color:#667eea;}\r\n      .foot{text-align:center;margin-top:30px;font-size:12px;color:#718096;}\r\n      @media print{body{padding:0;} .rc{border:none;}}\r\n    </style></head><body>\r\n    <div class=\"rc\">\r\n      <h1>Student Report Card</h1>\r\n      <p class=\"sub\">Academic Performance Report</p>\r\n      <div class=\"info\">\r\n        <div><b>Student Name</b>${escapeHtml(report.student?.name || 'N/A')}</div>\r\n        <div><b>Student ID</b>${escapeHtml(report.student?.studentId || 'N/A')}</div>\r\n        <div><b>Class</b>${escapeHtml(report.student?.class || 'N/A')}-${escapeHtml(report.student?.section || 'N/A')}</div>\r\n        <div><b>Generated By</b>${escapeHtml(genLabel)}</div>\r\n      </div>\r\n      <table>\r\n        <thead><tr><th>Subject</th><th>Marks Obtained</th><th>Max Marks</th></tr></thead>\r\n        <tbody>${subjectsHtml}</tbody>\r\n      </table>\r\n      <div class=\"totals\">\r\n        <div><b>${escapeHtml(report.grade || 'N/A')}</b>Overall Grade</div>\r\n        <div><b>${percentage}%</b>Percentage</div>\r\n      </div>\r\n      <p class=\"foot\">Generated on ${new Date().toLocaleDateString('en-IN',{year:'numeric',month:'long',day:'numeric'})}</p>\r\n    </div>\r\n    <script>window.onload=()=>window.print();<\\/script></body></html>`);\r\n  w.document.close();\r\n};\r\n\r\nwindow.deleteReportCard = async (reportId, studentName) => {\r\n  if (!confirm(`Delete report card for \"${studentName}\"?\\n\\nThis action cannot be undone.`)) return;\r\n  try {\r\n    await deleteDoc(doc(db, \"schools\", currentAdminId, \"reportCards\", reportId));\r\n    alert('Report card deleted successfully');\r\n    await loadAllReports();\r\n  } catch (error) {\r\n    console.error(\"Delete error:\", error);\r\n    alert('Error deleting report card');\r\n  }\r\n};\r\n\r\nfunction setReportModalOpen(isOpen) {\r\n  const modal = document.getElementById('reportModal');\r\n  if (!modal) return;\r\n  modal.style.display = isOpen ? 'block' : 'none';\r\n  modal.setAttribute('aria-hidden', isOpen ? 'false' : 'true');\r\n}\r\n\r\nwindow.closeModal = (event) => {\r\n  event?.preventDefault?.();\r\n  event?.stopPropagation?.();\r\n  setReportModalOpen(false);\r\n};\r\n\r\ndocument.getElementById('reportModal')?.addEventListener('click', (event) => {\r\n  if (event.target === event.currentTarget) setReportModalOpen(false);\r\n});\r\n\r\ndocument.addEventListener('keydown', (event) => {\r\n  if (event.key === 'Escape' && document.getElementById('reportModal')?.style.display !== 'none') {\r\n    setReportModalOpen(false);\r\n  }\r\n});\r\n\r\ndocument.getElementById('searchName').addEventListener('input', applyFilters);\r\ndocument.getElementById('searchStudentId').addEventListener('input', applyFilters);\r\ndocument.getElementById('searchClass').addEventListener('input', applyFilters);\r\ndocument.getElementById('gradeFilter').addEventListener('change', applyFilters);\r\ndocument.getElementById('termFilter').addEventListener('change', applyFilters);\r\n\r\n"},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""},{"attributes":{"src":"admin-shell.js?v=navbar-20260721"},"text":""}]};
